mapper.update:
UPDATE email_verification
SET attempt_count = attempt_count + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND verified_at IS NULL
  AND attempt_count < #{maxAttempts}

UPDATE email_verification
SET verified_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND verified_at IS NULL
  AND expires_at > #{now}
  AND attempt_count < #{maxAttempts}

mapper.select:
SELECT COUNT(*) AS count,
       MIN(o.created_at) AS oldestSentAt
FROM outbox_event o
WHERE o.event_type = #{eventType}
  AND o.aggregate_type = #{aggregateType}
  AND o.status = #{status}
  AND o.created_at > #{since}
  AND JSON_UNQUOTE(JSON_EXTRACT(o.payload, '$.requestIp')) = #{requestIp}
  AND NOT EXISTS (
      SELECT 1
      FROM email_verification v
      WHERE v.outbox_event_id = o.id
  )
